import { Component, inject, input, signal, OnInit, DestroyRef } from '@angular/core';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { HttpClient } from '@angular/common/http';
import { environment } from '../../../../environments/environment';

@Component({
  selector: 'app-pdf-viewer',
  templateUrl: './pdf-viewer.component.html',
  host: { class: 'd-block' },
})
export class PdfViewerComponent implements OnInit {
  private readonly sanitizer = inject(DomSanitizer);
  private readonly http = inject(HttpClient);
  private readonly destroyRef = inject(DestroyRef);

  readonly documentoId = input<number | null>(null);
  readonly url = input<string | null>(null);

  readonly loading = signal(true);
  readonly error = signal(false);
  readonly blobUrl = signal<SafeResourceUrl | null>(null);

  ngOnInit(): void {
    const directUrl = this.url();
    if (directUrl) {
      this.loadExternalUrl(directUrl);
      return;
    }

    const docId = this.documentoId();
    if (docId != null) {
      this.loadDocument(docId);
      return;
    }

    this.loading.set(false);
    this.error.set(true);
  }

  private loadExternalUrl(url: string): void {
    this.loading.set(false);
    this.blobUrl.set(this.sanitizer.bypassSecurityTrustResourceUrl(url));
  }

  private loadDocument(id: number): void {
    this.http
      .get(`${environment.apiUrl}/documentos/${id}`, {
        responseType: 'arraybuffer',
      })
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: (data) => {
          const blob = new Blob([data], { type: 'application/pdf' });
          const url = URL.createObjectURL(blob);
          this.blobUrl.set(this.sanitizer.bypassSecurityTrustResourceUrl(url));
          this.loading.set(false);
        },
        error: () => {
          this.loading.set(false);
          this.error.set(true);
        },
      });
  }
}
